#!/usr/bin/env python3
"""Numerical demonstrations for the cyclotomic coherence threshold model.

The arithmetic connection count is Euler's totient phi(n).  For a prime p this
is p - 1.  The modeled critical count is 10,000 and the coherence law is
sqrt(kappa) * sqrt(E - 10,000) above threshold, and zero otherwise.

Only the Python standard library is required.
"""

from __future__ import annotations

from dataclasses import dataclass
from math import isqrt, sqrt
from typing import Iterable

CRITICAL_EDGES: int = 10_000
PRIME_CONDUCTOR_CUTOFF: int = 10_001


def is_prime(n: int) -> bool:
    """Return whether n is prime using deterministic trial division."""
    if n < 2:
        return False
    if n in (2, 3):
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    divisor = 5
    while divisor <= isqrt(n):
        if n % divisor == 0 or n % (divisor + 2) == 0:
            return False
        divisor += 6
    return True


def euler_totient(n: int) -> int:
    """Compute Euler's totient phi(n) by trial-division factorization."""
    if n <= 0:
        raise ValueError("the conductor must be a positive integer")
    result = n
    remainder = n
    prime = 2
    while prime * prime <= remainder:
        if remainder % prime == 0:
            while remainder % prime == 0:
                remainder //= prime
            result -= result // prime
        prime = 3 if prime == 2 else prime + 2
    if remainder > 1:
        result -= result // remainder
    return result


def connection_count(conductor: int) -> int:
    """Return the cyclotomic character count E(n) = phi(n)."""
    return euler_totient(conductor)


def coherence(kappa: float, edges: int, critical: int = CRITICAL_EDGES) -> float:
    """Evaluate the square-root coherence order parameter."""
    if kappa < 0:
        raise ValueError("kappa must be nonnegative")
    if edges <= critical:
        return 0.0
    return sqrt(kappa) * sqrt(edges - critical)


def prime_coherence(kappa: float, prime: int) -> float:
    """Evaluate coherence at a prime conductor, checking primality first."""
    if not is_prime(prime):
        raise ValueError(f"{prime} is not prime")
    return coherence(kappa, prime - 1)


def primes_between(lower: int, upper: int) -> list[int]:
    """List primes p satisfying lower <= p <= upper."""
    return [n for n in range(max(2, lower), upper + 1) if is_prime(n)]


@dataclass(frozen=True)
class PhaseRecord:
    """One row in a conductor phase table."""

    conductor: int
    prime: bool
    connections: int
    phase: str
    coherence: float


def classify(conductors: Iterable[int], kappa: float = 1.0) -> list[PhaseRecord]:
    """Classify arbitrary conductors using their exact totient counts."""
    rows: list[PhaseRecord] = []
    for n in conductors:
        edges = connection_count(n)
        value = coherence(kappa, edges)
        rows.append(PhaseRecord(n, is_prime(n), edges,
                                "active" if value > 0.0 else "inactive", value))
    return rows


def print_table(rows: Iterable[PhaseRecord]) -> None:
    """Print phase records in an aligned plain-text table."""
    print(f"{'n':>8} {'prime':>7} {'E(n)':>8} {'phase':>10} {'C_kappa':>12}")
    print("-" * 51)
    for row in rows:
        print(f"{row.conductor:8d} {str(row.prime):>7} {row.connections:8d} "
              f"{row.phase:>10} {row.coherence:12.6f}")


def verify_prime_threshold(lower: int = 9_900, upper: int = 10_150) -> None:
    """Check the threshold equivalence on every prime in a finite interval."""
    for p in primes_between(lower, upper):
        arithmetic_side = connection_count(p) > CRITICAL_EDGES
        conductor_side = p > PRIME_CONDUCTOR_CUTOFF
        assert connection_count(p) == p - 1
        assert arithmetic_side == conductor_side
    print(f"Checked the prime threshold equivalence on [{lower}, {upper}].")


def main() -> None:
    """Run three demonstrations of counting, thresholding, and scaling."""
    print("Cyclotomic arithmetic coherence model")
    print(f"Critical connection count: {CRITICAL_EDGES:,}")
    print(f"Prime conductor cutoff:   {PRIME_CONDUCTOR_CUTOFF:,}\n")

    # Demonstration 1: values on both sides of the prime boundary.
    representative = [9973, 10009, 10037, 10111]
    print("Prime conductors around the transition (kappa = 1):")
    print_table(classify(representative, kappa=1.0))

    # Demonstration 2: changing coupling changes amplitude, not activation.
    print("\nCoupling sweep at the first active prime, p = 10009:")
    for kappa in (0.25, 1.0, 4.0, 9.0):
        print(f"  kappa={kappa:4.2f} -> coherence={prime_coherence(kappa, 10009):.6f}")

    # Demonstration 3: composite conductors need not follow the prime cutoff.
    print("\nPrime/composite comparison:")
    print_table(classify([10009, 10010, 12000, 15015, 20011], kappa=1.0))

    verify_prime_threshold()


if __name__ == "__main__":
    main()
